import React, { useState, useEffect } from 'react';
import axios from 'constants'; // or 'axios'

export default function TeacherReports() {
  const [results, setResults] = useState([
    { id: 101, student_name: "Kasun Perera", grade: "Grade 9", subject_name: "Mathematics", quiz_title: "Term Test Mock Quiz", marks_obtained: 85, total_marks: 100, status: "Pass" },
    { id: 103, student_name: "Ruwan Fernando", grade: "Grade 9", subject_name: "English", quiz_title: "Grammar Quiz 01", marks_obtained: 75, total_marks: 100, status: "Pass" }
  ]);
  const [statusFilter, setStatusFilter] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');

  // (අනාගතයේදී ගුරුවරයාට අදාළ විෂයන් වල ළමුන්ගේ දත්ත පමණක් මෙතනින් ඩේටාබේස් එකෙන් ඇදගත හැක)

  const filteredResults = results.filter(r => (r.student_name || '').toLowerCase().includes(searchQuery.toLowerCase()) && (statusFilter === 'All' || r.status === statusFilter));

  const handleDownloadPDF = () => {
    const printWindow = window.open('', '_blank');
    let tableRows = '';
    filteredResults.forEach((r, index) => {
      tableRows += `<tr><td>${index+1}</td><td>${r.student_name}</td><td>${r.grade}</td><td>${r.subject_name}</td><td>${r.quiz_title}</td><td>${r.marks_obtained}/${r.total_marks}</td><td>${((r.marks_obtained/r.total_marks)*100).toFixed(0)}%</td><td style="color:${r.status==='Pass'?'#16a34a':'#dc2626'}">${r.status}</td></tr>`;
    });
    printWindow.document.write(`<html><head><title>Student Performance Report</title><style>body{font-family:sans-serif;padding:40px;}h1{text-align:center;color:#15803d;border-bottom:3px solid #15803d;padding-bottom:15px;}table{width:100%;border-collapse:collapse;margin-top:20px;}th,td{border:1px solid #cbd5e1;padding:12px;text-align:left;font-size:13px;}th{background-color:#f8fafc;}</style></head><body><h1>STUDENT PERFORMANCE REPORT (FACULTY VIEW)</h1><table><thead><tr><th>No.</th><th>Student Name</th><th>Grade</th><th>Subject</th><th>Quiz Title</th><th>Marks</th><th>Percentage</th><th>Status</th></tr></thead><tbody>${tableRows}</tbody></table><script>window.onload=function(){window.print();window.close();}</script></body></html>`);
    printWindow.document.close();
  };

  return (
    <div style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '16px', boxShadow: '0 4px 12px rgba(0,0,0,0.02)' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
        <h3 style={{ margin: 0, color: '#1e293b', fontSize: '16px', fontWeight: 'bold' }}>📝 Student Academic Performance Matrix</h3>
        <div style={{ display: 'flex', gap: '12px' }}>
          <input type="text" placeholder="Search student..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} style={{ padding: '8px 12px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '13px' }} />
          <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} style={{ padding: '8px 12px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '13px', backgroundColor: 'white' }}>
            <option value="All">All Status</option>
            <option value="Pass">Passed Only</option>
            <option value="Fail">Failed Only</option>
          </select>
          <button onClick={handleDownloadPDF} style={{ padding: '8px 15px', backgroundColor: '#b91c1c', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' }}>📋 Download PDF</button>
        </div>
      </div>
      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
            <th style={{ padding: '12px 10px', color: '#64748b', fontSize: '13px', textAlign: 'left' }}>No.</th>
            <th style={{ padding: '12px 10px', color: '#64748b', fontSize: '13px', textAlign: 'left' }}>Student Name</th>
            <th style={{ padding: '12px 10px', color: '#64748b', fontSize: '13px', textAlign: 'left' }}>Grade</th>
            <th style={{ padding: '12px 10px', color: '#64748b', fontSize: '13px', textAlign: 'left' }}>Subject</th>
            <th style={{ padding: '12px 10px', color: '#64748b', fontSize: '13px', textAlign: 'left' }}>Quiz Title</th>
            <th style={{ padding: '12px 10px', color: '#64748b', fontSize: '13px', textAlign: 'left' }}>Marks</th>
            <th style={{ padding: '12px 10px', color: '#64748b', fontSize: '13px', textAlign: 'left' }}>Percentage</th>
            <th style={{ padding: '12px 10px', color: '#64748b', fontSize: '13px', textAlign: 'left' }}>Status</th>
          </tr>
        </thead>
        <tbody>
          {filteredResults.map((r, index) => (
            <tr key={index} style={{ borderBottom: '1px solid #f1f5f9' }}>
              <td style={{ padding: '14px 10px', fontSize: '13px' }}>{index + 1}</td>
              <td style={{ padding: '14px 10px', fontSize: '13px', fontWeight: 'bold', color: '#1e293b' }}>{r.student_name}</td>
              <td style={{ padding: '14px 10px', fontSize: '13px' }}>{r.grade}</td>
              <td style={{ padding: '14px 10px', fontSize: '13px', color: '#0284c7' }}>{r.subject_name}</td>
              <td style={{ padding: '14px 10px', fontSize: '13px' }}>{r.quiz_title}</td>
              <td style={{ padding: '14px 10px', fontSize: '13px' }}>{r.marks_obtained} / {r.total_marks}</td>
              <td style={{ padding: '14px 10px', fontSize: '13px', fontWeight: 'bold' }}>{((r.marks_obtained/r.total_marks)*100).toFixed(0)}%</td>
              <td style={{ padding: '14px 10px', fontSize: '13px' }}><span style={{ padding: '4px 10px', borderRadius: '12px', fontSize: '11px', fontWeight: 'bold', backgroundColor: r.status === 'Pass' ? '#dcfce7' : '#fee2e2', color: r.status === 'Pass' ? '#15803d' : '#b91c1c' }}>{r.status}</span></td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
